        "feedbackId": "BOS.ACT01.FB.TRANSFER.STRONG",
        "category": "STRONG_EVIDENCE",
        "authored": true,
        "reviewStatus": "AUTHOR_DRAFT",
        "text": "You carried the idea into a new situation and explained why it fits. That is the real test of understanding a concept."
